const datatranscript = $input.first().json.transcript;

// Return array with just the fields you need
return datatranscript.map(entry => ({
  json: {
    display_name: entry.speaker.display_name,
    text: entry.text,
    timestamp: entry.timestamp
  }
}));

// Convert JSON transcript to readable text format
const items = $input.all();
let output = [];

for (const item of items) {
  if (item.json.data && Array.isArray(item.json.data)) {
    let transcript = '';

    // Loop through each conversation entry
    for (const entry of item.json.data) {
      // Format: [timestamp] Name: Text
      transcript += `[${entry.timestamp}] ${entry.display_name}: ${entry.text}\n`;
    }

    output.push({
      json: {
        transcript: transcript.trim()
      }
    });
  }
}

return output;

