import json
import re

# Get the raw output from Slack messaging LLM
raw_output = _input.first().json['output']

# Extract JSON from markdown code blocks
# Remove ```json and ``` wrappers
json_match = re.search(r'```json\s*\n(.*?)\n```', raw_output, re.DOTALL)
if json_match:
    json_str = json_match.group(1)
else:
    # Fallback: try to find JSON by braces
    first_brace = raw_output.find('{')
    last_brace = raw_output.rfind('}')
    if first_brace != -1 and last_brace != -1:
        json_str = raw_output[first_brace:last_brace + 1]
    else:
        json_str = raw_output

# Parse the JSON
try:
    slack_data = json.loads(json_str)

    # Extract the main components
    headline = slack_data['headline']
    criteria_raw = slack_data['criteria']

    # Slack expects literal "\n" in strings, not actual newline characters
    # json.loads() converts "\n" to actual newlines, so we need to convert them back
    criteria = {}
    for key, value in criteria_raw.items():
        # Replace actual newline characters with the literal "\n" string for Slack
        criteria[key] = value.replace('\n', '\n\n')

    # Validate we have exactly 11 criteria
    if len(criteria) != 11:
        print(f"⚠️ WARNING: Expected 11 criteria but got {len(criteria)}")

    # Return structured data ready for Slack API
    return {
        'error': None,  # No error - success case
        'headline': headline,
        'criteria': criteria,  # Now contains "\\n" instead of actual newlines
        'criteria_count': len(criteria),
        'validation': {
            'has_headline': bool(headline),
            'has_11_criteria': len(criteria) == 11,
            'all_criteria_have_content': all(
                isinstance(v, str) and len(v.strip()) > 0
                for v in criteria.values()
            ),
            'all_criteria_have_newlines': all(
                '\n\n' in v for v in criteria.values()
            )  # Verify each criterion has the "\\n" escape sequence
        }
    }

except json.JSONDecodeError as e:
    # If parsing fails, return error info
    return {
        'error': 'Failed to parse JSON from LLM output',
        'error_details': str(e),
        'raw_output': raw_output[:500]
    }

import json
import re

# Initialize success flag
success = False
error_type = None
error_details = None

try:
    # Get the raw output from the LLM
    raw_output = _input.first().json.get('output')

    # Check if output exists
    if raw_output is None:
        raise ValueError("No 'output' field found in input data")

    # Convert to string if needed
    if not isinstance(raw_output, str):
        raw_output = str(raw_output)

    # Check if output is not empty
    if not raw_output or len(raw_output.strip()) == 0:
        raise ValueError("Output field is empty")

    # Method 1: Try regex to extract JSON from markdown
    json_match = re.search(r'```json\s*\n?(.*?)\n?```', raw_output, re.DOTALL)

    if json_match:
        json_str = json_match.group(1).strip()
    else:
        # Method 2: Find JSON by looking for curly braces
        first_brace = -1
        last_brace = -1

        for i in range(len(raw_output)):
            if raw_output[i] == '{' and first_brace == -1:
                first_brace = i
            if raw_output[i] == '}':
                last_brace = i

        # Extract the JSON string
        if first_brace != -1 and last_brace != -1:
            json_str = raw_output[first_brace:last_brace + 1]
        else:
            # If no braces found, assume it's already clean JSON
            json_str = raw_output.strip()

    # Validate we have something to parse
    if not json_str or len(json_str) < 2:
        raise ValueError("Could not extract valid JSON structure from output")

    # Parse the JSON
    evaluation_data = json.loads(json_str)

    # Validate required top-level fields
    required_fields = ['call_metadata', 'evaluations', 'summary']
    missing_fields = [field for field in required_fields if field not in evaluation_data]

    if missing_fields:
        raise ValueError(f"Missing required fields: {', '.join(missing_fields)}")

    # Validate evaluations array
    if not isinstance(evaluation_data.get('evaluations'), list):
        raise ValueError("'evaluations' must be an array")

    if len(evaluation_data['evaluations']) != 11:
        raise ValueError(f"Expected 11 evaluations, got {len(evaluation_data['evaluations'])}")

    # Validate each evaluation has required fields
    for idx, evaluation in enumerate(evaluation_data['evaluations']):
        required_eval_fields = ['criterion', 'rating', 'score', 'reasoning']
        missing_eval_fields = [field for field in required_eval_fields if field not in evaluation]

        if missing_eval_fields:
            raise ValueError(f"Evaluation {idx + 1} missing fields: {', '.join(missing_eval_fields)}")

    # All validations passed
    success = True

    # Return successful result
    return {
        'success': True,
        'data': evaluation_data,
        'validation': {
            'has_all_fields': True,
            'criteria_count': len(evaluation_data['evaluations']),
            'has_metadata': 'call_metadata' in evaluation_data,
            'has_summary': 'summary' in evaluation_data
        }
    }

except json.JSONDecodeError as e:
    # JSON parsing failed
    error_type = 'json_parse_error'
    error_details = {
        'error': 'Failed to parse JSON',
        'error_type': error_type,
        'message': str(e),
        'position': f"Line {e.lineno}, Column {e.colno}" if hasattr(e, 'lineno') else 'Unknown',
        'raw_output_preview': raw_output[:500] if 'raw_output' in locals() else 'N/A'
    }

except ValueError as e:
    # Validation or extraction failed
    error_type = 'validation_error'
    error_details = {
        'error': 'Validation failed',
        'error_type': error_type,
        'message': str(e),
        'raw_output_preview': raw_output[:500] if 'raw_output' in locals() else 'N/A'
    }

except KeyError as e:
    # Missing expected keys in input
    error_type = 'missing_input_key'
    error_details = {
        'error': 'Missing required input key',
        'error_type': error_type,
        'message': f"Key not found: {str(e)}",
        'raw_output_preview': 'Input structure issue'
    }

except Exception as e:
    # Catch-all for unexpected errors
    error_type = 'unexpected_error'
    error_details = {
        'error': 'Unexpected error occurred',
        'error_type': error_type,
        'message': str(e),
        'exception_type': type(e).__name__,
        'raw_output_preview': raw_output[:500] if 'raw_output' in locals() else 'N/A'
    }

# If we got here and success is still False, return error details
if not success:
    return {
        'success': False,
        'data': None,
        'error_info': error_details
    }

