let webhookData = null;

try {
  if (Array.isArray(inputData) && inputData.length > 0) {

    // Check if body exists
    if (inputData[0].body) {
      // Production: body is an array
      if (Array.isArray(inputData[0].body) && inputData[0].body.length > 0) {
        webhookData = inputData[0].body[0];
      }
      // Test: body is an object
      else if (typeof inputData[0].body === 'object' && !Array.isArray(inputData[0].body)) {
        webhookData = inputData[0].body;
      }
    }
    // Fallback: Nested data array structure
    else if (inputData[0]?.data?.[0]?.body) {
      if (Array.isArray(inputData[0].data[0].body)) {
        webhookData = inputData[0].data[0].body[0];
      } else {
        webhookData = inputData[0].data[0].body;
      }
    }
    // Fallback: json.body structure
    else if (inputData[0]?.json?.body) {
      if (Array.isArray(inputData[0].json.body)) {
        webhookData = inputData[0].json.body[0];
      } else {
        webhookData = inputData[0].json.body;
      }
    }
  }

} catch (error) {
  // Return error info for debugging
  return {
    json: {
      error: "Could not parse webhook data",
      error_message: error.message,
      contains_gameplan: false,
      recording_id: null,
      advisor_email: null,
      title: null,
      data_found: false,
      data_complete: false
    }
  };
}

// Safely check if title contains 'gameplan' (case-insensitive)
const containsGameplan = webhookData?.title 
  ? webhookData.title.toLowerCase().includes('gameplan') 
  : false;

// Extract recording ID with fallback
const recordingId = webhookData?.recording_id || null;

// Extract advisor email with fallback
const advisorEmail = webhookData?.recorded_by?.email || null;

// Extract title with fallback
const title = webhookData?.title || null;

// Return the processed data
return {
  json: {
    contains_gameplan: containsGameplan,
    recording_id: recordingId,
    advisor_email: advisorEmail,
    title: title,
    data_found: !!webhookData,
    data_complete: !!(webhookData?.title && webhookData?.recording_id && webhookData?.recorded_by?.email)
  }
};

